codes.java:
import java.util.*;

public class Main {
    public static int[] minAndMax(int[] numbers) {
        int min = numbers[0], max = numbers[0];
        for (int n : numbers) {
            min = Math.min(min, n);
            max = Math.max(max, n);
        }
        return new int[]{min, max};
    }

    public static void main(String[] args) {
        int[] numbers = {4, 8, 1, 9};
        int[] result = minAndMax(numbers);
        int low = result[0], high = result[1];
        System.out.println(low + " " + high);     // 1 9
    }
}

codes.cpp:
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

pair<int, int> minAndMax(vector<int>& numbers) {
    int lo = *min_element(numbers.begin(), numbers.end());
    int hi = *max_element(numbers.begin(), numbers.end());
    return {lo, hi};
}

int main() {
    vector<int> numbers = {4, 8, 1, 9};
    auto [low, high] = minAndMax(numbers);
    cout << low << " " << high << endl;     // 1 9
    return 0;
}

