codes.python:
def is_even(n):
    return n % 2 == 0

def count_evens(numbers):
    count = 0
    for n in numbers:
        if is_even(n):
            count += 1
    return count

print(count_evens([1, 2, 3, 4, 5, 6]))   # 3

codes.java:
public class Main {
    public static boolean isEven(int n) {
        return n % 2 == 0;
    }

    public static int countEvens(int[] numbers) {
        int count = 0;
        for (int n : numbers) {
            if (isEven(n)) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        int[] numbers = {1, 2, 3, 4, 5, 6};
        System.out.println(countEvens(numbers));   // 3
    }
}

